/* Exact replica of Domain::CreateRegionIndexSets (lulesh-init.cc:401) for balance=0 */
static void regsizes(int numElem, int myRank, int numReg, int balance, long *sz)
{
    srand(myRank);
    int regionNum, regionVar, lastReg = -1, binSize;
    int elements; long nextIndex = 0, runto = 0;
    int costDenominator = 0;
    int *regBinEnd = malloc(numReg*sizeof(int));
    int *regNumList = malloc(numElem*sizeof(int));
    for (int i=0;i<numReg;++i){ costDenominator += (int)pow((double)(i+1),(double)balance); regBinEnd[i]=costDenominator; }
    while (nextIndex < numElem) {
        regionVar = rand() % costDenominator;
        int i = 0; while (regionVar >= regBinEnd[i]) i++;
        regionNum = ((i + myRank) % numReg) + 1;
        while (regionNum == lastReg) {
            regionVar = rand() % costDenominator;
            i = 0; while (regionVar >= regBinEnd[i]) i++;
            regionNum = ((i + myRank) % numReg) + 1;
        }
        binSize = rand() % 1000;
        if (binSize < 773) elements = rand() % 15 + 1;
        else if (binSize < 937) elements = rand() % 16 + 16;
        else if (binSize < 970) elements = rand() % 32 + 32;
        else if (binSize < 974) elements = rand() % 64 + 64;
        else if (binSize < 978) elements = rand() % 128 + 128;
        else if (binSize < 981) elements = rand() % 256 + 256;
        else elements = rand() % 1537 + 512;
        runto = elements + nextIndex;
        while (nextIndex < runto && nextIndex < numElem) { regNumList[nextIndex]=regionNum; nextIndex++; }
        lastReg = regionNum;
    }
    for (int r=0;r<numReg;++r) sz[r]=0;
    for (long i=0;i<numElem;++i) sz[regNumList[i]-1]++;
    free(regBinEnd); free(regNumList);
}

int main(void)
{
    int numReg = 11, cost = 64, balance = 0;
    int rep[11];
    for (int r=0;r<numReg;r++){
        if (r < numReg/2) rep[r]=1;
        else if (r < (numReg - (numReg+15)/20)) rep[r]=1+cost;
        else rep[r]=10*(1+cost);
    }
    printf("rep[] = "); for(int r=0;r<numReg;r++) printf("%d ", rep[r]); printf("\n\n");

    int ranks[] = {1,8,27,64,125,216};
    int s[]     = {300,150,100,75,60,50};
    printf("%6s %5s %12s %14s %14s %8s\n","ranks","-s","elem/rank","mean cost","max cost","imbal");
    for (int k=0;k<6;k++){
        long numElem = (long)s[k]*s[k]*s[k];
        long sz[11];
        double maxc = 0, sumc = 0;
        long maxreg_elems = 0;
        for (int r_=0; r_<ranks[k]; r_++){
            regsizes((int)numElem, r_, numReg, balance, sz);
            double c = 0;
            for (int r=0;r<numReg;r++) c += (double)sz[r]*rep[r];
            if (c > maxc) maxc = c;
            sumc += c;
            /* size of the single most expensive region (rep=650) on this rank */
            if (sz[10] > maxreg_elems) maxreg_elems = sz[10];
        }
        double mean = sumc/ranks[k];
        printf("%6d %5d %12ld %14.4e %14.4e %8.4f   (worst reg10 = %ld elems)\n",
               ranks[k], s[k], numElem, mean, maxc, maxc/mean, maxreg_elems);
    }
    return 0;
}
